def descargar(base, nombre, leer):
    import os
    ruta_completa = os.path.abspath(os.path.join(base, nombre))
    base_absoluta = os.path.abspath(base)
    if not os.path.commonpath([ruta_completa, base_absoluta]) == base_absoluta:
        raise PermissionError("Acceso no permitido fuera del directorio base")
    if not os.path.isfile(ruta_completa):
        raise PermissionError("El recurso solicitado no es un archivo válido")
    return leer(ruta_completa)

import os

def descargar(base, nombre, leer):
    '''Contenido de un archivo público dentro de la carpeta base. `leer(ruta)` lee un archivo.'''
