    ruta = os.path.join(base, nombre)
    ruta_real = os.path.realpath(ruta)
    base_real = os.path.realpath(base)
    if os.path.commonpath([ruta_real, base_real]) != base_real:
        raise PermissionError("Acceso no permitido a la ruta: {}".format(ruta))
    return leer(ruta_real)

